sys_script.script:
(function executeRule(current, previous) {

    // Only check when a new complaint is created
    if (!current.isNewRecord()) {
        return;
    }

    // Need a description to compare
    if (current.description.nil()) {
        return;
    }

    // Normalize the new complaint description
    var newDescription = current.getValue('description')
        .toString()
        .toLowerCase()
        .trim();

    // Search existing complaints
    var gr = new GlideRecord('x_1972268_societ_0_society_complaint_case');
    gr.addQuery('description', current.getValue('description'));
    gr.setLimit(1);
    gr.query();

    // If a matching complaint already exists
    if (gr.next()) {
        current.duplicate_case = true;

        gs.addInfoMessage(
            'A similar complaint already exists: ' + gr.getValue('number')
        );
    }

})(current, previous);
